INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(1100, 0, 11, 0, 0, 0, 'Wetlands', 'The Wetlands are a vast, cold marsh lying between the mountains of Khaz Modan and the sea, cloaked in mist beneath a sky that rarely clears. This was once dwarven country, dotted with Ironforge strongholds and overlooked by Grim Batol, the old seat of the Wildhammer clan, but war after war has reduced most of those holds to rubble. Today the Alliance clings to the coast at Menethil Harbor, a port raised after the Second War and named for King Terenas Menethil II. Inland, nothing is secure. Remnants of the Dragonmaw orcs have crept out of the eastern hills to threaten the harbor and choke the pass at Dun Algaz. Dark Iron dwarves have wrecked one of the two bridges of the Thandol Span and seized Dun Modr. Red dragons guard the sealed gates of Grim Batol, while gnolls, murlocs, raptors and stranger things of the bog roam the fens between.', 'warcraft.wiki.gg/wiki/Wetlands_(Classic) (vast cold swamp, mists, ruined Ironforge strongholds, Wildhammer control, Menethil Harbor named for Terenas); warcraft.wiki.gg/wiki/Menethil_Harbor (rebuilt after the Second War); quest 455 description; quest 464 description; quest 303 description; quest 633 description (remaining bridge); warcraft.wiki.gg/wiki/Thandol_Span (one of the two bridges all but destroyed)'),
(1101, 1, 11, 1, 0, 0, 'Menethil Harbor', 'Menethil Harbor sits on the western shore of the Wetlands, the Alliance''s only stronghold in this dreary region. Orgrim Doomhammer first chose these waters as the place to build the Horde''s invasion fleet; after the Second War the site was rebuilt as an Alliance port under Grand Admiral Daelin Proudmoore and named in honor of King Terenas Menethil II. Its stone keep, where Captain Stoutfist keeps his war room, watches over a town of merchants, tanners and sailors, and the Deepwater Tavern is never short of a pint or a tale. Ships sail from its docks across the sea to Theramore, and the crocolisk hides cured here are shipped to ports around the world.', 'warcraft.wiki.gg/wiki/Menethil_Harbor (Doomhammer''s fleet site, rebuilt under Daelin Proudmoore, named for Terenas); warcraft.wiki.gg/wiki/Wetlands_(Classic) (the Alliance''s only presence in this dreary region); quest 473 description (Stoutfist in the keep''s war room); quest 942 description (Deepwater Tavern); quest 484 description (cured crocolisk skins shipped to ports around the world); transports table: Lady Mehley to Theramore, Northspear to Valgarde; npc_text 823 (Innkeeper Helbrek: stories to tell and kegs to empty)'),
(1102, 1, 11, 2, 0, 0, 'Menethil Bay', 'South of the harbor, the shallows of Menethil Bay hide the wreck of the Flying Osprey, an elven destroyer that sailed with the Kul Tiras Third Fleet for protection while carrying a cargo of Lightforge Iron, a metal prized because weapons forged from it strike with holy truth. The dragons that sank the fleet did not spare her either. Her waterlogged chest still lies in the shallows beside the wreck, and Bluegill raiders prowl the water all around it. Crocolisks bask along the muddy shore, and stranglekelp and iron coral grow thick beneath the water.', 'quest 321 description and reward text (Flying Osprey, elvish destroyer, Lightforge Iron, wrecked south of Menethil, murloc claw marks); quest 270 description (items crafted from it strike with holy truth); quests 324, 526 (murloc raiders near the wreck carry the ingots); zone_areas: Waterlogged Chest 2734, Bluegill Raider x11, Wetlands Crocolisks, Stranglekelp and Iron Coral in area 299'),
(1103, 1, 11, 3, 0, 0, 'Baradin Bay', 'Baradin Bay is the wide grey water washing the western coast of the Wetlands, with Menethil Harbor set upon its shore. Long before the harbor existed, Orgrim Doomhammer chose a small island in this bay as the place to build the fleet the Horde would turn against the Alliance in the Second War. Today the shallows are thick with stranglekelp and giant clams, Bluegill murlocs raid along the beaches, and the giant crocolisks of the northern coast are so dangerous that the town tanner''s own apprentice lost a leg trying to skin them.', 'warcraft.wiki.gg/wiki/Wetlands (Doomhammer chose a small island in Baradin Bay for his invasion fleet); warcraft.wiki.gg/wiki/Wetlands_(Classic) (Menethil Harbor sits in Baradin Bay); quest 471 description and request text (giant crocs north up the coast; apprentice left with one leg); zone_areas: Stranglekelp, Giant Clam, Bluegill murlocs and Giant Wetlands Crocolisk in area 298'),
(1104, 1, 11, 4, 0, 0, 'Bluegill Marsh', 'North of Menethil Harbor, Bluegill Marsh is a muddy stretch of coast where murlocs have crawled up out of the deep water to build their hovels. The Bluegill tribe harasses fishers and merchants along the road, and the boldest of them, a murloc called Gobbler, harries merchants on the coast road before slipping back to the safety of the huts by the river inlet. When the merchant ship Blind Princess was raided, much of her cargo was dragged overboard and scattered through these hovels, among it a very valuable statuette of Terenas Menethil that Karl Boran of the harbor wants recovered.', 'quest 279 description (murlocs building villages, Gobbler harries merchants, river inlet); quest 281 description (Blind Princess raided, Menethil Statuette); quest 286 description (silvery figurine of a young long-haired paladin with hammer upraised); DB: Gobbler 1259 spawn in area 1022; Bluegill murlocs, Battered Footlockers, Half-buried Barrel and Damaged Crate in area 1022'),
(1105, 1, 11, 5, 0, 0, 'The Lost Fleet', 'Off the northern coast lie the wrecks of the Kul Tiras Third Fleet, sent to the bottom during the Second War when red dragons ridden by Dragonmaw orcs fell upon it with fire. The fleet does not rest. Its lone survivor swears that something terrible was hidden aboard one of the ships, locked in the strongbox of the Intrepid, and that its eerie power binds the souls of the drowned crew to the rotting hulls. Cursed sailors and marines still shamble across the broken decks hungry for the living, and Captain Halyndor, whom his surviving first mate blames for leading them all to their doom, walks the Intrepid still with the strongbox key.', 'quest 288 description (attacked by red dragons controlled by orcs); quest 289 description (souls trapped in the hulls, wrecked off the coast to the north); quest 290 description (strongbox on the Intrepid, Captain Halyndor holds the key); quest 292 description (Cursed Eye of Paleth); quest 321 description (sunk by red dragons during the last Great War); creature_text 1239 (Curse you, Halyndor! You led us to our doom!); creature_text 1157/1158 (Brains..., Time to join us); warcraft.wiki.gg/wiki/The_Lost_Fleet (Third Fleet, Intrepid, Second War); DB: Captain Halyndor 1160, Cursed Sailor/Marine and Intrepid''s Locked Strongbox in area 1039'),
(1106, 1, 11, 6, 0, 0, 'Saltspray Glen', 'Saltspray Glen lies in the far northwest of the Wetlands, between Bluegill Marsh and the open waters of Baradin Bay. It takes its name from the sea: when a strong wind blows in off the bay, the waves fling salt water far across the grass. Raptors hunt its slopes and crocolisks wallow in its streams, but its most troubling inhabitants are the fen creepers, bog creatures risen out of the marsh like fevered blisters on the land, and the larger fen lords that walk with them.', 'warcraft.wiki.gg/wiki/Saltspray_Glen (location, name from seawater thrown inland, raptors); quest 275 description (Fen Creepers have risen, diseased blisters on the land); zone_areas: Highland Lashtail/Scytheclaw/Razormaw, Wetlands Crocolisk, Fen Creeper and Fen Lord in area 1023; warcraft.wiki.gg/wiki/Saltspray_Glen (bordered by Bluegill Marsh to the south, Baradin Bay to the north and west)'),
(1107, 1, 11, 7, 0, 0, 'Sundown Marsh', 'Sundown Marsh spreads across the north of the Wetlands, a broad fen of reeds and standing water. It is Mosshide country. Gnoll trappers, brutes and mystics roam its pools under their alphas, and a notorious Mosshide named Gnawbone prowls among them. A wandering bog creature called Mirelow rises from the muck, and crocolisks lurk in every channel. Even so, trade goes on: by an old mill near the road, a pair of dwarven and gnomish merchants sell engineering parts and special goods to Alliance travellers on the road.', 'zone_areas: Mosshide Trapper/Brute/Mystic/Alpha, Gnawbone 14425, Mirelow 14424, crocolisks, Wenna Silkbeard 2679 and Fradd Swiftgear 2682 in area 1024; warcraft.wiki.gg/wiki/Fradd_Swiftgear (pre-Cataclysm: located by a mill in Sundown Marsh); creature_template subnames 2679 Special Goods Dealer, 2682 Engineering Supplies; creature_template 2679 faction 55, 2682 faction 875 (Alliance factions)'),
(1108, 1, 11, 8, 0, 0, 'Ironbeard''s Tomb', 'Just west of the road to Dun Modr stands Ironbeard''s Tomb, an ancient dwarven crypt beside a small graveyard, watched over by a statue presumed to be Ironbeard himself. It has become a sorry place. Oozes of black, crimson and monstrous kinds have seeped into the crypt and defiled it, and those who would bury their dead no longer come here. Sida of Menethil Harbor still made her weekly visit until the oozes set upon her; in her panic she flung her bag at one, and the creature simply swallowed it.', 'warcraft.wiki.gg/wiki/Ironbeard''s_Tomb (crypt west of the Dun Modr road, graveyard, statue presumably of Ironbeard, defiled by black, crimson and monstrous oozes, no one buries their dead there); quest 470 description (Sida''s weekly visit, bag swallowed by an ooze); zone_areas: Black Ooze, Crimson Ooze, Monstrous Ooze in area 309'),
(1109, 1, 11, 9, 0, 0, 'Dun Modr', 'Dun Modr is an old dwarven town in the north of the Wetlands, standing just south of the Thandol Span and long a strategic key to the whole region. While Ironforge''s soldiers fought for the Alliance in distant lands, the Dark Iron dwarves struck at home: they laid waste to the Span, then fell upon Dun Modr before its regiment could regroup. Most of the defenders were killed and Longbraid the Grim sounded the retreat. His survivors now hold a small camp outside the walls, waiting on reserves that never seem to come, while Dark Iron tunnelers, saboteurs and demolitionists swarm through the town.', 'warcraft.wiki.gg/wiki/Dun_Modr (just south of the Span, major strategic point, Dark Iron attack); quest 303 description and request text (soldiers abroad, Span laid waste, Dun Modr fell, reserve); quest 472 description (most of the regiment killed, Longbraid sounded the retreat); quest 634 description (awaiting the reserves of Ironforge); zone_areas: Longbraid 1071, Motley 1074, Rhag 1075, Roggo 1072, Ashlan 1073 and Dark Iron Dwarf/Tunneler/Saboteur/Demolitionist in area 205'),
(1110, 1, 11, 10, 0, 0, 'Thandol Span', 'The Thandol Span was raised by the dwarves of Ironforge after the War of the Three Hammers, two arches joining Khaz Modan to the lands of Lordaeron so that trade and kinship with the Wildhammers of Aerie Peak might endure. Now it lies half in ruin. When the Dark Irons struck, a tremendous explosion tore apart the west bridge and many of its defenders died, Longbraid''s own brother among them. The dwarves cling to the remaining bridge, their main supply line to the north, and an old scout sent to see whether it could be secured has sent back no word. Near it wanders Comar Villard, a grieving man still searching for some sign of his lost wife.', 'warcraft.wiki.gg/wiki/Thandol_Span (built after the War of the Three Hammers, two arches, Khaz Modan to Lordaeron, Wildhammer ties); quest 304 description (West Bridge destroyed, Longbraid''s brother); quest 633 description (Kam Deepfury mastermind, remaining bridge, major supply line to the north); quest 378 description (Deepfury conspirator); quest 1476 description (Comar Villard wandering the Wetlands for a sign of his wife); DB: Comar Villard 5683 and Ebenezer Rustlocke''s Corpse 2652 in area 881; quest 631 description (explosion, Rustlocke sent to scout, no word)'),
(1111, 1, 11, 11, 0, 0, 'Direforge Hill', 'Southeast of Dun Modr rises Direforge Hill, where the Dark Iron invaders have made their camp. From here their leader, the warlock Balgaras the Foul, directs the war on the Wetlands, sending tunnelers, saboteurs and demolitionists to do his fighting while he keeps to the safety of the hill. The survivors of Dun Modr despise him as a coward and have long tried to run him down. Raptors stalk the surrounding slopes, oozes creep through the gullies, and crimson and flamesnorting whelps flit among the rocks.', 'quest 304 description (Balgaras hides in his camp on Direforge Hill to the southeast, sends his soldiers, coward); quest 304 request text (he has been evading us); zone_areas: Balgaras the Foul 1364, Dark Iron Dwarf/Tunneler/Saboteur/Demolitionist, Highland raptors, oozes and Crimson/Flamesnorting/Lost Whelps in area 1016'),
(1112, 1, 11, 12, 0, 0, 'The Green Belt', 'The Green Belt is the marshy lowland east of the road where it forks toward Dun Modr, a tangle of fen and reed thick with crocolisks, oozes and young red whelps. Somewhere among the crocs, and worse, dwells the creature the folk of Menethil Harbor call the Greenwarden. An old sailor in the harbor thinks anyone who goes looking for it is a fool bent on dying: the beast, he says, will bite a traveller in half, so there is no sense in bringing any gold along.', 'quest 463 description (marsh east of the road where it forks to Dun Modr, lurking among the crocs, bites you in half); quest 463 reward text (many names, answers to Rethiel, lands weep from festered wounds); warcraft.wiki.gg/wiki/Rethiel_the_Greenwarden (bog beast); zone_areas: Rethiel 1244, Young Wetlands Crocolisk, oozes and red whelps in area 1025'),
(1113, 1, 11, 13, 0, 0, 'Whelgar''s Excavation Site', 'East of Menethil Harbor, the Explorers'' League dug into the marsh under Prospector Whelgar, with soldiers sent by Longbraid to watch over them. The dig turned up rare artifacts, great bones and the Goaz Stone, an ancient tablet whose broken text spoke of a divine plan and a doomed prophecy. Then the mottled raptors came. The pack overran the site, and the few who escaped, Whelgar among them, are trapped on a ridge above the ruined diggings, with one stout dwarf standing guard over them against the beasts. Fragments of the stone lie scattered among the artifacts and loose soil below.', 'quest 306 description (rare artifacts, large bones, raptors overwhelmed the site, Ormer defended them, trapped); quest 294 description (bones attracted the raptors, brethren killed); quest 299 description (Goaz Stone, divine plan, doomed prophecy, fragments in artifacts and loose soil); quest 299 reward text (Titan script); warcraft.wiki.gg/wiki/Longbraid_the_Grim (sent soldiers to accompany Whelgar); warcraft.wiki.gg/wiki/Whelgar''s_Excavation_Site (east of Menethil, ridge overlooking the dig); zone_areas: Whelgar 1077, Merrin 1076, Ormer 1078, Ancient Relic and Loose Soil objects in area 118; page_text 93-94 (Merrin''s Letter: battalion from Longbraid''s regiment, only 3 survived)'),
(1114, 1, 11, 14, 0, 0, 'Angerfang Encampment', 'In the hills east of Whelgar''s Excavation lies the Angerfang Encampment, stronghold of the Dragonmaw orcs in the Wetlands. When their red dragon slaves broke free at the end of the Second War, the clan was all but destroyed, and the few survivors fled Grim Batol into these mountains. Here they have slowly regained their strength under Chieftain Nek''rosh. Raiders, swamprunners, bonewarders and shadowwarders crowd the camp beneath its war banners, and great wooden catapults stand among the tents.', 'quest 464 description (Dragonmaws all but destroyed, fled Grim Batol into the mountains east of Whelgar''s Excavation, encampment northeast of Menethil, war banners); quest 465 description (catapults to lay siege to Menethil, in the Dragonmaw encampment); warcraft.wiki.gg/wiki/Nek''rosh (based at the Angerfang Encampment); zone_areas: Chieftain Nek''rosh 2091, Dragonmaw Raider/Swamprunner/Bonewarder/Shadowwarder/Centurion, Dragonmaw Catapult 1609 in area 1036'),
(1115, 1, 11, 15, 0, 0, 'Grim Batol', 'In the eastern mountains stands Grim Batol, where Thane Khardros founded the kingdom of the Wildhammer clan. When the Dark Irons made war on their kin, Modgud, wife of the sorcerer-thane Thaurissan, led the assault on it and laid a curse of shadow upon it, and though Khardros slew her, the Wildhammers found their home tainted and left. In the Second War the Dragonmaw clan under the warlock Nekros made it their stronghold, using the Demon Soul to hold the Dragonqueen Alexstrasza captive, until Rhonin and his companions destroyed the artifact. The freed red dragons tore Grim Batol apart in their fury. Now its gates are sealed, and red dragonkin, among them the lieutenant Axtroz, guard them against all comers.', 'warcraft.wiki.gg/wiki/Grim_Batol (Khardros, Modgud''s curse, uninhabitable, Dragonmaw occupation, sealed and guarded by red dragonkin including Axtroz; pre-Cataclysm sections only); page_text 2019-2021 (The Battle of Grim Batol, book in Menethil Harbor: Nekros, Demon Soul, Alexstrasza, Rhonin, dragons tore Grim Batol apart); quest 6585 description (the Red Flight now guards Grim Batol, their lieutenant Axtroz); zone_areas: Axtroz 12899, Scalebane Royal Guard, Wyrmkin Firebrand, Red Scalebane, Red Dragonspawn in area 1038'),
(1116, 1, 11, 16, 0, 0, 'Mosshide Fen', 'Mosshide Fen lies in the south of the Wetlands, not far from the dwarven gate at Algaz, and it is the home ground of the Mosshide gnolls. For many years the Mosshides lived in these marshes peacefully enough, but their numbers have swollen. Their feet trample the fen''s bushes and flowers, and their axes take more wood than the land can spare to feed their fires, until the gnolls are no longer in balance with the land. Gnolls, mongrels and fenrunners roam the pools with their mistweavers, sharing the fen with young crocolisks and black slimes.', 'quest 276 description (Mosshides lived peacefully many years, growing in numbers, stamp flat bushes and flowers, axes cut too much wood; hunt them to the south near the Dwarven gate of Algaz); quest 277 description; zone_areas: Mosshide Gnoll/Mongrel/Fenrunner/Mistweaver, Young Wetlands Crocolisk, Black Slime in area 1020'),
(1117, 1, 11, 17, 0, 0, 'Thelgen Rock', 'Thelgen Rock is a great cavern in the southern Wetlands, northwest of the Algaz Gate, that runs deep into the mountains. Spiders infest it, the leech stalkers, and a monstrous one known as the Leech Widow hunts in the marsh nearby. Yet the cave holds a prize. Veins of incendicite run through its rock, a rare ore so volatile it is hard to work without blowing oneself up, which one dwarven pilot of Dun Morogh hopes, smelted the right way, could make cannon shells that pack a mighty punch.', 'warcraft.wiki.gg/wiki/Thelgen_Rock (cavern deep into the mountains, spiders, incendicite); quest 466 description (incendicite in a cave northwest of Algaz Gate, volatile, cannon shells; given by Pilot Stonegear 1377, QuestSortID 1 Dun Morogh); zone_areas: Leech Stalker 1111 x22 in area 1021; Leech Widow 1112 spawn at -3780,-2344 (area 11, just outside); creature_template 1111/1112 family 3 (spider)'),
(1118, 1, 11, 18, 0, 0, 'The Northern Algaz Road', 'North of the dwarven gate, the pass of Dun Algaz winds down out of the mountains into the Wetlands, and its road runs on to the fork where travellers turn west for Menethil Harbor. This northern stretch is Dragonmaw ground now. Orc scouts and grunts who usually keep to their hills have come down in force to hold the road, roaring for the Dragonmaw at any who pass, and their warlord Ma''ruk Wyrmscale waits near the Wetlands end. Only a few Ironforge mountaineers patrol the southern approach. While the orcs hold the pass, no relief can reach Menethil by land, and at first no one at the harbor could say what drove the clan into Algaz.', 'quest 455 description and reward text (Menethil is through Dun Algaz, north along the road, then west at the fork; Dragonmaws normally hide in the hills; their surge into Algaz a mystery to Valstag Ironjaw); quest 465 description (fighting in Dun Algaz blocks reinforcements to Menethil; used in part 1); creature_text 2102/2103 (For the Dragonmaw!); zone_areas: Dragonmaw Scout x17, Grunt x16, Ma''ruk Wyrmscale 2090 <Dragonmaw Warlord> at -4207,-2377 (north end), patrolling Mountaineers Grugelm, Dokkin, Thar, Rharen near the southern end in area 836'),
(1119, 2, 11, 1, 1, 0, 'Captain Stoutfist', 'Captain Stoutfist commands the defense of Menethil Harbor from the war room inside its keep, and his position is an uneasy one. The Dragonmaw orcs are showing their strength well beyond their hills: they have pushed into Dun Algaz, threatening to cut the harbor off from Loch Modan, and their encampment northeast of town has grown strong again. With no soldiers to spare, Stoutfist calls upon any capable volunteer, first sending them to attack the Angerfang camp and bring back its war banners as proof. He knows the clan''s history well, from its days as master of the red dragons to its near destruction when they turned on it.', 'quest 473 description (in the keep, in the war room); quests 464, 465, 474 (descriptions and reward texts); creature_template 2104 faction 55 (Ironforge)'),
(1120, 2, 11, 2, 1, 0, 'Longbraid the Grim', 'Longbraid the Grim led the dwarven regiment that guarded Dun Modr and the Thandol Span. When the Dark Irons struck, his own brother died as the west bridge over the Span was destroyed, and before the regiment could regroup Dun Modr was overrun. Longbraid sounded the retreat and sent the wounded Harlo Barnaby to safety on the only surviving horse. Now he holds a camp outside the fallen town with what remains of his soldiers, a shadow of the great regiment they once were. He means to see the warlock Balgaras, who has long evaded his hunters, slain, and he waits on reserves from Ironforge that have yet to arrive.', 'quest 161 description (regiment guarding Dun Modr and the Thandol Span); quest 472 description and reward text; quest 304 description (brother died when the West Bridge was destroyed); quest 634 description and reward text (Captain Nials: he is on his own); warcraft.wiki.gg/wiki/Longbraid_the_Grim; creature_template 1071 faction 55'),
(1121, 2, 11, 3, 0, 0, 'Chieftain Nek''rosh', 'Nek''rosh is chieftain of the Dragonmaw clan in the Wetlands and son of Nekros Skullcrusher, the warlock who once held the red Dragonqueen captive in Grim Batol. When the magic that bound the dragons failed, they turned on their masters, slew Nekros and hunted the clan almost to extinction. Nek''rosh has sworn revenge on the dragons who killed his father. From the Angerfang Encampment he has rebuilt the clan''s strength while his warriors pushed into Dun Algaz, and he has raised catapults to besiege Menethil Harbor. He is seldom found without a guard of warriors about him.', 'quest 464 description and reward text (son of Nekros, magic failed, Nekros killed, vowed revenge); quest 465 description; warcraft.wiki.gg/wiki/Nek''rosh (Nek''rosh Skullcrusher, son of Nekros Skullcrusher, Angerfang, usually guarded by five orcs); page_text 2019 (Nekros held Alexstrasza in Grim Batol)'),
(1122, 2, 11, 4, 0, 0, 'Balgaras the Foul', 'Balgaras the Foul is the Dark Iron warlock who leads his clan''s invasion of the Wetlands, the campaign that tore apart the Thandol Span and took Dun Modr. He counts himself among the minions of Ragnaros, proclaims that the Dark Irons will reclaim their rightful lands, and promises to leave his foes nothing but ash and dust. To the dwarves of Ironforge he is a coward who sends his soldiers to do his bidding while he hides in his camp on Direforge Hill, and he has evaded their hunters for a long time.', 'creature_text 1364 (minions of Ragnaros, reclaim their rightful lands, ash and dust); quest 304 description and reward text; warcraft.wiki.gg/wiki/Dun_Modr (Dark Irons led by Balgaras); quest 304 request text (he has been evading us)'),
(1123, 2, 11, 5, 1, 0, 'Rethiel the Greenwarden', 'Rethiel is a great bog beast of the Green Belt, known in Menethil Harbor as the Greenwarden and called a monster by an old sailor there. He says he has many names but answers to only a few. To Rethiel the Wetlands are a living thing, wounded and weeping: fen creepers have risen as fevered blisters on the land, and the Mosshide gnolls, once in balance, now trample the fens and burn living wood. He asks those the roots and ferns speak well of to heal these wounds, and to begin by thinning the gnolls.', 'quest 463 description and reward text; quests 275, 276, 277 (descriptions and reward texts); warcraft.wiki.gg/wiki/Rethiel_the_Greenwarden (bog beast, formerly Stormwind-affiliated); creature_template 1244 faction 12 (Stormwind)'),
(1124, 2, 11, 6, 1, 0, 'First Mate Fitzsimmons', 'Fitzsimmons was first mate of the Wave Mistress, a ship of the line in the Kul Tiras Third Fleet, and he is the only survivor of the dragonfire that sank the fleet off the Wetlands coast. He has washed up in Menethil Harbor, where he drinks away his days, begs for mead and, by his own cheerful admission, smells. He curses his old captain, Halyndor, for leading them all to their doom. Yet he has not forgotten his shipmates. In his dreams he hears their moans, their souls held in the wrecks by a cursed treasure, and he longs for someone brave enough to set them free.', 'quests 288, 289, 290 (descriptions and texts); creature_text 1239; quest 292 request text (Glorin calls him that drunk Fitzsimmons); creature_template 1239 faction 12'),
(1125, 2, 11, 7, 1, 0, 'Prospector Whelgar', 'Prospector Whelgar of the Explorers'' League led the dig that bears his name, east of Menethil Harbor. Just before mottled raptors overran the site he unearthed the Goaz Stone, a large tablet whose translated text breaks off in four places, speaking of a divine plan and a doomed prophecy. Now he is trapped on a ridge above the ruined dig with Merrin Rockweaver and their protector Ormer Ironbraid, too old, he admits, to brave the beasts below, and he fears time is running out. He also keeps a fossil that Archaeologist Flagongut is eager to study.', 'quest 299 description and reward text; quest 306 description; quest 943 description (Whelgar holds the original fossil); creature_text 1077 (I figured Flagongut would send someone for that fossil); creature_template 1077 subname Explorers'' League, faction 55'),
(1126, 2, 11, 8, 1, 0, 'Mikhail', 'Mikhail tends bar in Menethil Harbor, having left Stormwind a few years ago and settled here to retire. He greets every guest with talk of ale and mutton, but he still keeps friends in the capital, among them Elling Trias, and a visitor who comes in Elling''s name finds his hospitality multiplied tenfold, so long as the name is spoken quietly: such business is not for the whole tavern to hear. Old habits die hard. He admits, though never where Elling might hear, that he misses the excitement of his old underground work.', 'quest 1248 description and reward text; quest 1249 description and reward text (misses the underground excitement, never tell Elling); creature_template 4963 faction 12; gossip 1100 / npc_text 1713 (period text, not used)'),
(1127, 3, 11, 1, 1, 0, 'The Dragonmaw Threat', 'Word reached Loch Modan that the Dragonmaw orcs, who usually keep to their hills, had surged into Dun Algaz in force. If they held the pass, Loch Modan would be cut off from Menethil Harbor, so the mountaineers called for volunteers to break through. Those who reached Menethil found the orcs rising across the Wetlands, and no one at the harbor could say what had driven them into Algaz. In the keep, Captain Stoutfist told the clan''s story: broken when their red dragons turned on them after the Second War, the survivors fled Grim Batol for the eastern mountains and have grown strong again in an encampment northeast of town. Stoutfist wants that camp attacked and its war banners brought back as proof.', 'quests 468, 455, 473, 464, 465, 474 (descriptions and reward texts)'),
(1128, 3, 11, 2, 1, 0, 'The Fall of Dun Modr', 'War rages at home and abroad for the dwarves of Ironforge. While their soldiers give their lives for the Alliance in distant lands, the Dark Iron dwarves have struck in the Wetlands. In Menethil Harbor a soldier named Harlo Barnaby woke with an axe wound in his back and terrible news: Dun Modr had fallen. The Dark Irons had ambushed the defenders of the Thandol Span and fallen on the town before its regiment could regroup, killing most of it. As Longbraid the Grim sounded the retreat horn, Harlo was struck down, and he remembers nothing more. He still hopes his commander lives, somewhere near the fallen town.', 'quests 472, 303, 304, 378 (descriptions, request and reward texts)'),
(1129, 3, 11, 3, 1, 0, 'The Thandol Span', 'A tremendous explosion roared through the hills when the Dark Irons struck the Thandol Span, and good soldiers died defending it. The west bridge lies in ruins, and the remaining one is now the dwarves'' only crossing to the north. Longbraid has sworn revenge, but with Dun Modr under siege and no reinforcements in sight, his regiment is stretched thin. Days ago he sent Ol'' Ebenezer Rustlocke to scout the eastern bridge and see whether it could be secured, and no word has come back. Rhag Garmason has no one to spare for a search, and asks a willing stranger to look for the old dwarf.', 'quests 631, 632, 633, 634 (descriptions and reward texts)'),
(1130, 3, 11, 4, 1, 0, 'The Doomed Fleet', 'The Third Fleet of Kul Tiras met its end off the Wetlands coast, burned and sunk by red dragons ridden by Dragonmaw orcs. Its lone survivor, First Mate Fitzsimmons of the Wave Mistress, will tell the tale to anyone who buys him a drink: his drowned brothers still walk the wrecks, bound by a terrible thing hidden aboard the Intrepid. Freeing them means cutting down the cursed crew, taking the strongbox key from Captain Halyndor, who still walks his ship, and bringing whatever lies inside to the dwarven priest Glorin Steelbrow in town. The same fleet once sheltered the elven ship Flying Osprey, and her lost Lightforge Iron still draws those seeking holy weapons to the bay.', 'quests 288, 289, 290, 292, 293 (descriptions and reward texts); quest 270 The Doomed Fleet description (Third Fleet sunk off the Wetlands, Lightforge Iron aboard one ship, sent to Glorin Steelbrow); quest 321 (Flying Osprey and its Lightforge Iron, mentioned only)'),
(1131, 3, 11, 5, 1, 0, 'The Whelgar Excavation', 'Tarrel Rockweaver of Menethil Harbor had a letter every week from his wife Merrin, who was digging with the Explorers'' League east of town under Prospector Whelgar. Then nearly two weeks passed in silence. Longbraid had promised to send a scout if no word came, and Tarrel is sure something is wrong. In Menethil, Archaeologist Flagongut has troubles of his own. Whelgar holds a fossil the archaeologist means to study, and on the road to meet him Flagongut was set upon by raptors and lost the Stone of Relu, the relic he believes is the key to the fossil''s mystery. One of the mottled beasts swallowed it.', 'quests 305, 306 (descriptions and reward texts); quests 294, 295, 296; quest 299 description and reward text; quests 942, 943 (descriptions)'),
(1132, 3, 11, 6, 1, 0, 'The Greenwarden''s Charge', 'Ask about the Greenwarden in Menethil Harbor and an old sailor will call you a fool: the beast lurks among the crocs in the marsh east of the Dun Modr road, he says, and bites travellers in half, so there is no sense in bringing any gold. Yet something is plainly amiss in the Wetlands. The Mosshide gnolls, peaceful for many years, have multiplied until they trample the fen''s bushes and flowers and cut down its trees to feed their fires, and fevered fen creepers have risen to shamble through the waterways.', 'quests 463, 276, 277, 275 (descriptions and reward texts)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(1101, 1, 13, 255, 'Since the Alliance took its war to the Lich King, the docks have served a second route. The Northspear now sails from Menethil for Valgarde, the Alliance port on the Howling Fjord in Northrend, and the harbor that once watched the Horde build its fleet sends Alliance soldiers north to the new front.', 'transports table: Northspear (181688), Menethil Harbor to Valgarde, Howling Fjord; warcraft.wiki.gg/wiki/Valgarde (Alliance port in the Howling Fjord)'),
(1104, 1, 0, 255, 'The statuette was not in the first hovels searched, nor in the next. It turned up at last in the north of the marsh, in a barrel half buried in the mud and grass and still packed in fine straw: a silvery figurine of a young, long-haired paladin with his hammer upraised. Karl Boran saw it returned, to the great relief of the Blind Princess''s captain.', 'quests 284, 285 descriptions (no trace in the first hovels); quest 286 description and reward text (half-buried barrel, silvery figurine, captain relieved); gameobject_queststarter 259 (Half-buried Barrel starts 286)'),
(1105, 1, 0, 255, 'The rusted key taken from Captain Halyndor fit the lock of the Intrepid''s strongbox. Inside lay the treasure the first mate had spoken of, the thing he blamed for holding the dead to their ships: a blackened orb pulsing with an eerie light, a Cursed Eye of Paleth.', 'quest 290 reward text (the rusted key fits); quest 292 description (blackened orb, Cursed Eye of Paleth); gameobject 112948 Intrepid''s Locked Strongbox (ends 290, starts 292)'),
(1110, 1, 0, 255, 'The Dark Irons were not finished with the Span. Kam Deepfury, the mastermind of the first attack, had arranged for a cache of explosives to be hidden just across the bridge in the Arathi Highlands, ready to bring down the last arch. The cache was found and destroyed in time, and the remaining bridge still carries the dwarves'' road north.', 'quest 633 description and reward text (Deepfury the mastermind, cache across the Span, remaining bridge saved)'),
(1112, 1, 0, 255, 'Those who seek the Greenwarden out find no man-eater but a great bog beast who says he has many names and answers to only a few, Rethiel among them. He listens to the roots and ferns of the marsh, and he grieves for a land that weeps from festering wounds.', 'quest 463 reward text (many names, answers to Rethiel, lands weep from festered wounds); warcraft.wiki.gg/wiki/Rethiel_the_Greenwarden (bog beast)'),
(1114, 1, 0, 255, 'The catapults are no idle work. Menethil''s defenders learned that Nek''rosh means to turn them on the harbor and lay siege to it, while the fighting his warriors keep up in Dun Algaz leaves the town effectively blocked from reinforcements.', 'quest 465 description (catapults to lay siege to Menethil, blocked from reinforcements)'),
(1118, 1, 0, 255, 'A likely answer came when Captain Stoutfist''s men uncovered more of the Dragonmaw''s plans. Chieftain Nek''rosh has built catapults to lay siege to Menethil Harbor, and with the fighting in Dun Algaz the town is effectively cut off from any reinforcements that might save it.', 'quest 465 description (catapults, siege of Menethil, fighting in Dun Algaz blocks reinforcements)'),
(1119, 1, 0, 255, 'The banners were taken, and Stoutfist judged the Dragonmaw no longer the threat they were with dragons, though still fierce opponents. Then his men uncovered their chieftain''s gambit: Nek''rosh had built catapults to besiege Menethil, while the fighting in Dun Algaz kept reinforcements away. Stoutfist sent the volunteers back with tinder to burn the engines, and with orders to cut the beast down at its neck.', 'quest 464 reward text; quest 465 description'),
(1119, 2, 0, 255, 'With the catapults burned and Nek''rosh slain, Stoutfist declared Menethil Harbor safe. He called it a telling blow to the Dragonmaw clan, one from which they may never recover, and saw that the kingdom of Ironforge rewarded those who had served it so well.', 'quest 474 reward text'),
(1120, 1, 0, 255, 'When the ear of Balgaras the Foul was brought to him, Longbraid allowed that the warlock''s death could not bring back the innocent dwarves who had died by his hand, though it would ease the minds of those who survived. The leaderless invaders should be easy enough to manage, he said, and must be wiped out before a new leader is sent.', 'quest 304 reward text'),
(1120, 2, 0, 255, 'Hoping for help from any quarter, his officers sent a plea north to the Alliance at Refuge Pointe. Captain Nials offered her condolences and nothing more: Stromgarde itself had fallen, and her soldiers were sworn to retake it first. The reply came back to Longbraid that he was on his own.', 'quest 634 description and reward text (Rhag sends the plea; Nials: he is on his own)'),
(1121, 1, 0, 255, 'Nek''rosh fell at last in the Angerfang Encampment, his vow of revenge on the red dragons unfulfilled. In Menethil Harbor his death was hailed as a telling blow to the Dragonmaw clan, one from which it may never recover, and with his catapults burned the harbor was safe.', 'quest 474 reward text'),
(1122, 1, 0, 255, 'Balgaras was run down on Direforge Hill at last and slain, and his ear carried to Longbraid as proof. His death could not undo the many needless deaths he had caused, but with their leader gone the remaining Dark Irons of the Wetlands looked easy prey, if they could be wiped out before a new leader was sent.', 'quest 304 reward text'),
(1123, 1, 0, 255, 'Once the Mosshides'' numbers were reduced, Rethiel admitted that his faith in the peoples of the Alliance has been sorely taxed in the past. It may yet be restored, he allows, by those who tend to the health of the Wetlands.', 'quest 276 reward text'),
(1123, 2, 0, 255, 'He wanted the gnolls'' crude flints taken too, the tools they use to make fire. Once they were in his hands he vowed to smash them and cast them into the sea, so that they could never again be used to burn living wood.', 'quest 277 description and reward text'),
(1125, 1, 0, 255, 'Once the four lost fragments, Ados, Modr, Golm and Neru, were dug out of the ruined site, the Goaz Stone was whole again and Whelgar returned to his delicate translation of its Titan script. The first new words he made out spoke of Old Gods, chained beneath the land. This, he says, is the beginning of something epic.', 'quest 299 description and reward text'),
(1126, 1, 0, 255, 'Trias''s message asked after a man called Slim. The name meant nothing to Mikhail, but he promised to keep his eyes open, and he was quick to notice a gentleman by the tavern''s exit listening to the conversation a little too intently.', 'quest 1248 reward text; quest 1249 description (offered on the 1248 turn-in)'),
(1127, 1, 0, 255, 'The raid on the Angerfang Encampment told Stoutfist much. The clan answers to Nek''rosh, son of the warlock Nekros, whose hold over the dragons failed and cost him his life, and the son has sworn revenge on the dragons who slew his father. Worse, Stoutfist''s men uncovered Nek''rosh''s gambit: catapults built to besiege Menethil, while the fighting in Algaz kept any reinforcements away.', 'quest 464 reward text; quest 465 description'),
(1127, 2, 0, 255, 'The catapults were put to the torch one by one, and Nek''rosh himself was slain in his camp. Stoutfist called it a telling blow from which the Dragonmaw may never recover, and with the siege engines gone, Menethil Harbor was safe.', 'quest 465 completion and reward text; quest 474 reward text'),
(1128, 1, 0, 255, 'Longbraid was alive, holding a camp outside Dun Modr with what remained of his soldiers, a shadow of the great regiment they had been. Harlo, he explained, had been sent away on the only surviving steed. Now Motley Garmason calls for pressure on the Dark Iron encampment while Roggo Harlbarrow struggles to reach the reserves, and Longbraid wants the cowardly warlock Balgaras the Foul slain in his camp on Direforge Hill.', 'quest 472 reward text; quest 303 description and request text; quest 304 description'),
(1128, 2, 0, 255, 'Balgaras was slain at last and his ear laid before Longbraid. It could not bring back the dwarves who had died by his hand, but it gave the survivors some peace of mind, and Longbraid resolved to finish the leaderless Dark Irons before a new leader could be sent to them.', 'quest 304 reward text'),
(1128, 3, 0, 255, 'Vengeance reached further still. Roggo gathered proof that Kam Deepfury was a conspirator in the attack on the Span, and that it was by his planning that Longbraid lost his brother. Deepfury is held in the Stormwind Stockade for political reasons, and Motley, bound by honor to stay at Longbraid''s side, will not let human bureaucracy stand between a Dark Iron and justice.', 'quest 378 description and request text'),
(1128, 4, 0, 255, 'Kam Deepfury died in the Stockade, and Motley took grim satisfaction in hearing that the Dark Iron had met the death he dealt to others. The families of the Span''s victims could know he had been punished, and Longbraid''s brother was avenged.', 'quest 378 reward text'),
(1129, 1, 0, 255, 'Rustlocke was found near the Span, dead. The name engraved on the small dwarven helmet left no doubt, and every sign pointed to a Dark Iron ambush. Clutched in his fist was a parchment, which had to go back to Rhag Garmason.', 'quest 631 reward text; quest 632 description; gameobject 2652 Ebenezer Rustlocke''s Corpse (ends 631, starts 632)'),
(1129, 2, 0, 255, 'The parchment was grave news. Kam Deepfury, the mastermind behind the first attack, had arranged for a cache of explosives to be stashed just across the Span in the Arathi Highlands. If those explosives reached the bridge, the dwarves'' major supply line to the north would be severed, and Rhag would not let Rustlocke die in vain.', 'quest 633 description (offered on the 632 turn-in)'),
(1129, 3, 0, 255, 'The cache was destroyed in time and the remaining bridge was saved, a great service to King Magni and the people of Khaz Modan. Still the regiment could not hold out forever, so Rhag sent to the Alliance camp at Refuge Pointe in the north, asking Captain Nials for soldiers to help retake Dun Modr and the Span.', 'quest 633 reward text; quest 634 description'),
(1129, 4, 0, 255, 'Captain Nials could spare none. She grieved for Longbraid''s soldiers, but Stromgarde itself had fallen, and honor and duty held her people in the highlands until the king''s banner flew over their city again. She would send word to Longbraid that he was on his own.', 'quest 634 reward text'),
(1130, 1, 0, 255, 'Inside the strongbox lay a blackened orb pulsing with an eerie light, a Cursed Eye of Paleth. Glorin had never heard that the Third Fleet carried such an Eye, and said it was no wonder Fitzsimmons was so spooked. He could not lift the curse himself, for the Eyes were crafted by human priests, so it had to go to Archbishop Benedictus in Stormwind.', 'quest 292 description and reward text; quest 293 description (offered on the 292 turn-in)'),
(1130, 2, 0, 255, 'Benedictus saw at once that this Eye had witnessed a terrible tragedy. The Eyes were made to shine bright, he explained, and their powers grow dangerous when tainted, so he cleansed the orb himself, drawing out the taint that Fitzsimmons had blamed for binding his brothers to their ships.', 'quest 293 reward text; quest 290 description (it must be retrieved and cleansed to free them)'),
(1131, 1, 0, 255, 'Merrin was found alive, with grim news. The team had begun uncovering great bones when mottled raptors overwhelmed the dig, and nearly everyone perished, the soldiers from Longbraid''s regiment among them. Only Merrin, Whelgar and the laborer Ormer Ironbraid survived, Ormer shielding the others as they ran. Now they are trapped on a ridge above the ruins, while Whelgar frets over the scattered fragments of the Goaz Stone, a tablet that speaks of a divine plan and a doomed prophecy.', 'quest 306 description; page_text 93-94 (Merrin''s letter: Longbraid''s battalion, nearly everyone perished, 3 survived, Ormer a laborer); quest 294 description; quest 299 description'),
(1131, 2, 0, 255, 'Ormer swore vengeance for his fallen brethren, and the raptors of the dig paid dearly for it. Their leader, he reckoned, was Sarltooth, bigger and more menacing than the rest, and when its talon was brought to him he declared the memory of the fallen redeemed, and the beasts warned off King Magni''s subjects for good.', 'quests 294, 295, 296 (descriptions, request and reward texts)'),
(1131, 3, 0, 255, 'With the four fragments recovered from the ruined dig, the Goaz Stone was whole once more. Whelgar went back to his delicate translation of its Titan script and soon made out new words: Old Gods, chained beneath the land. The beginning, he believes, of something epic.', 'quest 299 reward text'),
(1131, 4, 0, 255, 'The Stone of Relu was taken back from the raptor that had swallowed it and carried to Flagongut, together with the fossil from Whelgar''s keeping. With the relic in hand, the archaeologist set to work deciphering the powers of the fossils, his own and Remtravel''s from Darkshore alike.', 'quest 943 description, request and reward texts'),
(1132, 1, 0, 255, 'Those who go anyway find Rethiel, a guardian of the fens who listens to the roots and ferns. The Wetlands, he says, weep from festering wounds. The Mosshides are no longer in balance with the land, and if the Wetlands are to survive, their numbers must be reduced.', 'quest 463 reward text; quest 276 description'),
(1132, 2, 0, 255, 'With the gnolls thinned, Rethiel allowed that his faith in the peoples who share his land, sorely taxed in the past, might yet be restored. He had their crude flints taken as well, to be smashed and cast into the sea so they could never again burn living wood. Then he turned to the fen creepers, diseased blisters on the land that must be put down so they can settle back into the marshes and the fever can break.', 'quest 276 reward text; quest 277 description and reward text; quest 275 description'),
(1132, 3, 0, 255, 'The fen creepers were put down and allowed to settle back into the marshes, and Rethiel declared the land soothed by the effort. For this he granted a boon to the one who had tended to the Wetlands'' wounds.', 'quest 275 description and reward text');
